"use client";

import { useState } from "react";

export default function SignupPage() {
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError("");
    setSuccess("");

    const formData = new FormData(e.currentTarget);

    try {
      const res = await fetch("/api/register", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();

      if (data.error) {
        setError(data.error);
      } else {
        setSuccess("Registratie succesvol! Je kunt nu inloggen.");
      }
    } catch (err: any) {
      setError("Er is iets misgegaan, probeer het opnieuw.");
    }
  }

  return (
    <div className="flex flex-col items-center justify-start min-h-screen bg-gray-50 px-4 pt-20">
      {/* Hero / Logo */}
      <div className="mb-12 flex flex-col items-center">
        <div className="w-24 h-24 rounded-full bg-gray-900 flex items-center justify-center text-white text-3xl font-bold shadow-lg">
          WS
        </div>
        <h1 className="mt-4 text-4xl font-bold text-gray-900">WorkSpace</h1>
        <p className="text-gray-600 mt-1 text-center">Organiseer je werk eenvoudig</p>
      </div>

      {/* Form */}
      <form
        onSubmit={handleSubmit}
        className="w-full max-w-md bg-white p-8 rounded-2xl shadow-xl space-y-6"
      >
        <h2 className="text-2xl font-semibold text-gray-800 text-center">
          Registreren
        </h2>

        <div className="flex flex-col gap-4">
          <input
            type="email"
            name="email"
            placeholder="E-mail"
            className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-400 focus:border-transparent transition"
            required
          />

          <input
            type="password"
            name="password"
            placeholder="Wachtwoord"
            className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-400 focus:border-transparent transition"
            required
          />
        </div>

        {error && <p className="text-red-600 text-center">{error}</p>}
        {success && <p className="text-green-600 text-center">{success}</p>}

        <button
          type="submit"
          className="w-full bg-gray-900 text-white p-3 rounded-lg font-semibold hover:bg-gray-800 transition shadow-md hover:shadow-lg"
        >
          Registreren
        </button>

        <p className="text-gray-500 text-sm text-center">
          Al een account?{" "}
          <a href="/signin" className="text-gray-900 font-medium hover:underline">
            Log hier in
          </a>
        </p>
      </form>
    </div>
  );
}